def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "~": 3, "^": 4}

    def apply_operator():
        op = operators.pop()

        if op == "~":
            values[-1] = -values[-1]
            return True

        b = values.pop()
        a = values.pop()

        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        elif op == "^":
            if b < 0:
                return False
            result = pow(a, b)
        else:
            if b == 0:
                return False
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            result = quotient if op == "/" else a - b * quotient

        values.append(result)
        return True

    i = 0
    expecting_operand = True

    while i < len(expr):
        ch = expr[i]

        if ch == " ":
            i += 1
        elif "0" <= ch <= "9":
            number = 0
            while i < len(expr) and "0" <= expr[i] <= "9":
                number = number * 10 + (ord(expr[i]) - ord("0"))
                i += 1
            values.append(number)
            expecting_operand = False
        elif ch == "(":
            operators.append(ch)
            i += 1
            expecting_operand = True
        elif ch == ")":
            while operators[-1] != "(":
                if not apply_operator():
                    return "error"
            operators.pop()
            i += 1
            expecting_operand = False
        elif ch == "-" and expecting_operand:
            operators.append("~")
            i += 1
        else:
            while (
                operators
                and operators[-1] != "("
                and (
                    precedence[operators[-1]] > precedence[ch]
                    or (precedence[operators[-1]] == precedence[ch] and ch != "^")
                )
            ):
                if not apply_operator():
                    return "error"
            operators.append(ch)
            i += 1
            expecting_operand = True

    while operators:
        if not apply_operator():
            return "error"

    return values[0]
